  '51': {
    description: "قناع GENOSYS BIO-FERMENT AGE DEFYING POWDER MASK هو قناع مسحوق مخمر مبتكر يجمع بين تقنية التخمير التقليدية وعلوم العناية بالبشرة الحديثة. هذه الصيغة الفريدة من المسحوق إلى القناع تنشط عند خلطها بالماء، مما يخلق علاجاً قوياً يوفر العناصر الغذائية المركزة والمركبات المفيدة مباشرة للبشرة للحصول على أقصى فوائد مضادة للشيخوخة.",
    productDetails: '{"form":"قناع مسحوق (ينشط بالماء)","size":"300غ","skinType":"جميع أنواع البشرة، خاصة البشرة الناضجة والشائخة","technology":"عملية التخمير الحيوي","keyBenefits":"مقاوم للشيخوخة، تجديد البشرة، ترطيب عميق","usage":"1-2 مرات في الأسبوع","origin":"كوريا الجنوبية"}',
    keyFeatures: null,
    benefits: '["مقاوم للشيخوخة - يقلل الخطوط الدقيقة والتجاعيد من خلال تقنية التخمير المتقدمة","تقنية التخمير الحيوي - يستغل قوة الكائنات الحية الدقيقة المفيدة لصحة البشرة","الاختراق العميق - صيغة المسحوق إلى القناع تضمن أقصى امتصاص للمكونات","الحماية المضادة للأكسدة - تحييد الجذور الحرة والأضرار البيئية","تجديد البشرة - يعزز دوران الخلايا للبشرة الأصغر سناً","تعزيز الترطيب - يوفر رطوبة مكثفة وتأثيرات انتفاخ","عمل التثبيت - يحسن مرونة البشرة ومتانتها"]',
    ingredients: '[{"name":"مستخلصات التخمير الحيوي","description":"عملية التخمير المتقدمة تخلق مركبات مفيدة وببتيدات وأحماض أمينية تعزز وظيفة حاجز البشرة وتوفر فوائد مضادة للشيخوخة من خلال العمليات البيولوجية الطبيعية."},{"name":"مستخلص الأرز المخمر","description":"غني بالفيتامينات والمعادن ومضادات الأكسدة، يوفر الأرز المخمر تقشيراً لطيفاً وتأثيرات تفتيح مع تغذية البشرة بالعناصر الغذائية الأساسية."},{"name":"مستخلص فول الصويا المخمر","description":"يحتوي على الإيزوفلافونات والببتيدات التي تساعد في تحسين مرونة البشرة وتقليل الالتهاب وتوفير الحماية المضادة للأكسدة ضد الضغوطات البيئية."},{"name":"مستخلص الشاي الأخضر المخمر","description":"خصائص مضادة للأكسدة محسنة من خلال التخمير، توفر حماية فائقة ضد الجذور الحرة وتساعد في تقليل علامات الشيخوخة والأضرار البيئية."},{"name":"مستخلص الجينسنغ المخمر","description":"مكون كوري تقليدي محسن من خلال التخمير، يوفر تأثيرات منشطة ومنعشة مع تحسين لون البشرة وتقليل علامات التعب."},{"name":"حمض الهيالورونيك","description":"يوفر ترطيباً مكثفاً وتأثيرات انتفاخ، مما يساعد في تقليل مظهر الخطوط الدقيقة والتجاعيد مع الحفاظ على مستويات رطوبة البشرة المثلى."}]',
    howToUse: "اخلط المسحوق بالماء أو السائل المفضل لديك لإنشاء عجينة ناعمة. ضع بالتساوي على البشرة النظيفة، مع تجنب منطقة العين. اتركه لمدة 15-20 دقيقة، ثم اشطفه جيداً بماء فاتر. استخدم 1-2 مرات في الأسبوع للحصول على أفضل النتائج.",
    directions: "هذا المنتج تم اختباره من قبل أطباء الجلد وهو آمن لجميع أنواع البشرة. للحصول على أفضل النتائج، استخدمه كجزء من روتين العناية بالبشرة الأسبوعي لتحقيق بشرة شابة ومتوهجة."
  },
