    productDetails: '{"form":"رذاذ إحياء متقدم","target":"استعادة وتوازن الميكروبيوم الطبيعي للبشرة","technology":"تقنية البروبيوتيك المتطورة مع مكونات الترطيب القوية","keyBenefits":"استعادة الميكروبيوم، ترطيب فوري، إشراق","usage":"استخدام يومي للرذاذ","skinType":"جميع أنواع البشرة","application":"رش على الوجه والرقبة","origin":"كوريا الجنوبية"}',
